from ui import *

def search(ph): return f'<label class="search">{icon("search")}<input type="search" placeholder="{ph}" aria-label="{ph}"></label>'
def avatar(n): return f'<span class="avatar"><img src="../assets/avatars/people/{n}.png" alt=""></span>'
def avatars(): return '<span class="avatars">'+avatar('10')+avatar('01')+avatar('07')+'</span>'
def checkrow(title,sub,art='pin',on=True):return f'<div class="row"><span class="row-art"><img src="../assets/fluent/{art}.svg" alt=""></span><div class="row-main"><p class="row-title">{title}</p><p class="row-sub">{sub}</p></div><span class="row-trail"><button class="check" role="checkbox" aria-checked="{str(on).lower()}" aria-label="{title} 선택"><span>{icon("check")}</span></button></span></div>'
def capsule(title,sub,slot,to='locked'):
 return f'<a class="row" href="{to}.html"><span class="thumb is-l"><img src="../assets/photos/{slot}.jpg" alt="장소 분위기 예시"></span><div class="row-main"><span class="badge">잠김</span><p class="row-title">{title}</p><p class="row-sub">{sub}</p></div><span class="row-trail">{icon("lock")}</span></a>'
def done_inline(text):return f'<p class="done">{icon("check")}{text}</p>'

